B.XN=new A.w(B.n,[B.ep,"\u090f\u0915\u094d\u091f\u093f\u0935 \u092c\u0928\u093e\u092e \u092a\u0948\u0938\u093f\u0935","\u0927\u094d\u0935\u0928\u093f \u092a\u094d\u0930\u0915\u093e\u0930","\u090f\u0915\u094d\u091f\u093f\u0935 5V \u092a\u0930 \u0916\u0941\u0926 \u092c\u091c\u0924\u093e \u0939\u0948; \u092a\u0948\u0938\u093f\u0935 \u0917\u093e\u0928\u0947 \u092c\u091c\u093e \u0938\u0915\u0924\u093e \u0939\u0948\u0964"],t.M)
B.XC=new A.w(B.n,[B.ei,"\u0930\u0947\u091c\u094b\u0928\u0947\u0902\u0938 \u092c\u0949\u0915\u094d\u0938","\u0927\u094d\u0935\u0928\u093f \u0935\u093f\u0938\u094d\u0924\u093e\u0930\u0915","\u092a\u094d\u0932\u093e\u0938\u094d\u091f\u093f\u0915 \u0915\u0948\u092a \u0906\u0935\u093e\u091c\u093c \u0915\u094b \u0924\u0947\u091c\u093c \u0915\u0930 \u0926\u0947\u0924\u0940 \u0939\u0948\u0964"],t.M)
